<"'!doctype html>
<html lang="en">
<head>
<meta charset="utf-8">
<meta name="viewport" content="width=device-width,initial-scale=1">
<title>Brick Breaker</title>
<style>
  :root{color-scheme:dark;--ink:#eef3ff;--muted:#9aa8c7;--panel:#111a32;--line:#263655;--cyan:#68e1fd;--pink:#ff79b8}
  *{box-sizing:border-box}
  body{margin:0;min-height:100vh;display:grid;place-items:center;padding:24px;background:radial-gradient(ellipse at 50% 0%,#1b2c52 0,#0b1020 58%,#080c17 100%);color:var(--ink);font:15px/1.4 system-ui,-apple-system,Segoe UI,sans-serif}
  .game{width:min(920px,100%)}
  header{display:flex;align-items:end;justify-content:space-between;gap:20px;margin:0 0 14px}
  h1{margin:0;font-size:clamp(24px,4vw,34px);letter-spacing:-1px}
  .sub{margin:4px 0 0;color:var(--muted);font-size:13px}
  .stats{display:flex;gap:10px}
  .stat{min-width:90px;padding:8px 13px;border:1px solid var(--line);border-radius:12px;background:#111a32d9;text-align:center}
  .stat span{display:block;color:var(--muted);font-size:10px;font-weight:700;letter-spacing:1.4px;text-transform:uppercase}
  .stat strong{display:block;margin-top:2px;font-size:19px;font-variant-numeric:tabular-nums}
  .board{position:relative;overflow:hidden;border:1px solid #344667;border-radius:17px;background:#0b1224;box-shadow:0 24px 70px #0008}
  canvas{display:block;width:100%;height:auto;touch-action:none}
  .overlay{position:absolute;inset:0;display:grid;place-items:center;padding:20px;background:#080d19a8;backdrop-filter:blur(4px);text-align:center}
  .overlay[hidden]{display:none}
  .card{max-width:400px;padding:28px 30px;border:1px solid #3b4f72;border-radius:18px;background:#111a32f2;box-shadow:0 16px 50px #0008}
  .card h2{margin:0 0 8px;font-size:28px;letter-spacing:-.7px}
  .card p{margin:0 0 19px;color:#b6c2dc}
  button{border:0;border-radius:10px;padding:11px 22px;background:linear-gradient(135deg,#69e4ff,#78aaff);color:#071321;font:700 15px system-ui;cursor:pointer}
  button:hover{filter:brightness(1.08);transform:translateY(-1px)}
  .help{display:flex;justify-content:space-between;gap:12px;margin-top:11px;color:var(--muted);font-size:12px}
  kbd{padding:2px 6px;border:1px solid #3a4b69;border-radius:5px;background:#141e35;color:#dce6ff;font:11px ui-monospace,monospace}
  @media(max-width:560px){body{padding:14px}.stat{min-width:66px;padding:7px 9px}.stats{gap:6px}.help{font-size:11px}.sub{font-size:12px}}
</style>
</head>
<body>
<main class="game">
  <header>
    <div><h1>BRICK BREAKER</h1><p class="sub">Clear both stages. Keep the ball in play.</p></div>
    <div class="stats" aria-label="Game stats">
      <div class="stat"><span>Score</span><strong id="score">0</strong></div>
      <div class="stat"><span>Lives</span><strong id="lives">3</strong></div>
      <div class="stat"><span>Level</span><strong id="level">1 / 2</strong></div>
    </div>
  </header>
  <section class="board" aria-label="Brick breaker game">
    <canvas id="canvas" width="900" height="560" aria-label="Game field"></canvas>
    <div class="overlay" id="overlay">
      <div class="card"><h2 id="title">Ready?</h2><p id="message">Move the paddle, then launch the ball. Break every brick to advance.</p><button id="action">Start game</button></div>
    </div>
  </section>
  <div class="help"><span>Move: <kbd>←</kbd> <kbd>→</kbd> or <kbd>A</kbd> <kbd>D</kbd> · Mouse also works</span><span>Launch / serve: <kbd>Space</kbd> or click</span></div>
</main>
<script>
(() => {
  const canvas=document.getElementById('"'canvas'), ctx=canvas.getContext('2d');
  const scoreEl=document.getElementById('score'), livesEl=document.getElementById('lives'), levelEl=document.getElementById('level');
  const overlay=document.getElementById('overlay'), titleEl=document.getElementById('title'), messageEl=document.getElementById('message'), actionBtn=document.getElementById('action');
  const W=900,H=560;
  let score=0,lives=3,level=1,running=false,over=false,serve=true,keys={},bricks=[],last=0;
  const paddle={x:W/2-58,y:H-43,w:116,h:13,speed:580};
  const ball={x:W/2,y:paddle.y-13,r:8,vx:0,vy:0};
  const colors=['#65d9ff','#7b9dff','#bd83ff','#ff78b7','#ff9b70'];
  function makeBricks(){
    bricks=[];
    const rows=level===1?5:6,cols=level===1?10:11,gap=9,bw=(W-100-(cols-1)*gap)/cols,bh=level===1?23:21;
    const top=level===1?78:64;
    for(let r=0;r<rows;r++) for(let c=0;c<cols;c++){
      if(level===2 && ((r===1||r===4)&&(c===0||c===cols-1))) continue;
      const stagger=level===2&&r%2?bw/2+gap/2:0;
      bricks.push({x:50+c*(bw+gap)+stagger,y:top+r*(bh+10),w:bw,h:bh,color:colors[(r+(level-1)*2)%colors.length],alive:true});
    }
  }
  function updateHud(){scoreEl.textContent=score;livesEl.textContent=lives;levelEl.textContent=level+' / 2'}
  function show(title,msg,button){titleEl.textContent=title;messageEl.textContent=msg;actionBtn.textContent=button;overlay.hidden=false}
  function hide(){overlay.hidden=true}
  function resetBall(){serve=true;ball.vx=0;ball.vy=0;ball.x=paddle.x+paddle.w/2;ball.y=paddle.y-ball.r-2}
  function start(){score=0;lives=3;level=1;running=true;over=false;paddle.x=W/2-paddle.w/2;makeBricks();resetBall();updateHud();hide()}
  function launch(){if("'!running||over)return;if(serve){serve=false;ball.vx=(Math.random()>.5?1:-1)*220;ball.vy=-360}}
  actionBtn.addEventListener('"'click',()=>{if("'!running||over)start();else if(serve){hide();launch()}});
  function pointerMove(e){const rect=canvas.getBoundingClientRect(),x=(e.clientX-rect.left)/rect.width*W;paddle.x=Math.max(0,Math.min(W-paddle.w,x-paddle.w/2));if(serve)resetBall()}
  canvas.addEventListener('"'pointermove',pointerMove);
  canvas.addEventListener('pointerdown',e=>{pointerMove(e);if("'!running||over)start();else launch()});
  window.addEventListener('"'keydown',e=>{const k=e.key.toLowerCase();if(['arrowleft','arrowright',' '].includes(k))e.preventDefault();keys[k]=true;if(k===' '){if(serve&&running)hide();launch()}});
  window.addEventListener('keyup',e=>{keys[e.key.toLowerCase()]=false});
  function collideRect(b){
    const nx=Math.max(b.x,Math.min(ball.x,b.x+b.w)),ny=Math.max(b.y,Math.min(ball.y,b.y+b.h));
    const dx=ball.x-nx,dy=ball.y-ny;
    if(dx*dx+dy*dy<ball.r*ball.r){
      const overlapX=ball.r-Math.abs(dx),overlapY=ball.r-Math.abs(dy);
      if(overlapX<overlapY)ball.vx=dx<0?-Math.abs(ball.vx):Math.abs(ball.vx);
      else ball.vy=dy<0?-Math.abs(ball.vy):Math.abs(ball.vy);
      return true;
    } return false;
  }
  function update(dt){
    if("'!running||over)return;
    if(keys.arrowleft||keys.a)paddle.x-=paddle.speed*dt;
    if(keys.arrowright||keys.d)paddle.x+=paddle.speed*dt;
    paddle.x=Math.max(0,Math.min(W-paddle.w,paddle.x));
    if(serve){ball.x=paddle.x+paddle.w/2;ball.y=paddle.y-ball.r-2;return}
    ball.x+=ball.vx*dt;ball.y+=ball.vy*dt;
    if(ball.x<ball.r){ball.x=ball.r;ball.vx=Math.abs(ball.vx)}
    if(ball.x>W-ball.r){ball.x=W-ball.r;ball.vx=-Math.abs(ball.vx)}
    if(ball.y<ball.r){ball.y=ball.r;ball.vy=Math.abs(ball.vy)}
    if(ball.vy>0 && ball.y+ball.r>=paddle.y && ball.y-ball.r<=paddle.y+paddle.h && ball.x>=paddle.x && ball.x<=paddle.x+paddle.w){
      ball.y=paddle.y-ball.r;
      const hit=(ball.x-(paddle.x+paddle.w/2))/(paddle.w/2);
      const speed=Math.min(570,Math.hypot(ball.vx,ball.vy)+8);
      ball.vx=hit*speed*.82;ball.vy=-Math.sqrt(speed*speed-ball.vx*ball.vx);
    }
    for(const b of bricks)if(b.alive&&collideRect(b)){b.alive=false;score+=level===1?10:20;updateHud();break}
    if(ball.y-ball.r>H){lives--;updateHud();if(lives<=0){running=false;over=true;show('"'Game over', 'Final score: '+score+'. Give it another shot?','Play again')}else resetBall()}
    if(bricks.every(b=>"'!b.alive)){
      if(level===1){level=2;makeBricks();resetBall();updateHud();show('"'Stage 1 clear"'!'"', 'Stage 2 is ready. Launch when you are set.','Continue')}
      else{running=false;over=true;show('You win"'!'"', 'Both stages cleared"'! Final score: '"'+score,'Play again')}
    }
  }
  function rounded(x,y,w,h,r){ctx.beginPath();ctx.roundRect(x,y,w,h,r);ctx.fill()}
  function draw(){
    ctx.clearRect(0,0,W,H);
    const bg=ctx.createLinearGradient(0,0,0,H);bg.addColorStop(0,'#0e1830');bg.addColorStop(1,'#091020');ctx.fillStyle=bg;ctx.fillRect(0,0,W,H);
    ctx.strokeStyle='#ffffff08';ctx.lineWidth=1;for(let x=30;x<W;x+=45){ctx.beginPath();ctx.moveTo(x,0);ctx.lineTo(x,H);ctx.stroke()}
    for(const b of bricks)if(b.alive){ctx.shadowColor=b.color;ctx.shadowBlur=9;ctx.fillStyle=b.color;rounded(b.x,b.y,b.w,b.h,6);ctx.shadowBlur=0;ctx.fillStyle='#ffffff44';rounded(b.x+3,b.y+3,b.w-6,3,2)}
    ctx.shadowColor='#60dfff';ctx.shadowBlur=18;ctx.fillStyle='#74e5ff';rounded(paddle.x,paddle.y,paddle.w,paddle.h,7);ctx.shadowBlur=0;
    ctx.shadowColor='#fff';ctx.shadowBlur=15;ctx.beginPath();ctx.arc(ball.x,ball.y,ball.r,0,Math.PI*2);ctx.fillStyle='#fff';ctx.fill();ctx.shadowBlur=0;
    if(running&&serve&&overlay.hidden){ctx.fillStyle='#b9c7e8';ctx.font='13px system-ui';ctx.textAlign='center';ctx.fillText('Press SPACE or click to launch',W/2,H-93)}
  }
  function frame(t){const dt=Math.min((t-last)/1000||0,0.033);last=t;update(dt);draw();requestAnimationFrame(frame)}
  makeBricks();resetBall();updateHud();requestAnimationFrame(frame);
})();
</script>
</body>
</html>
